def transform(grid):
    h, w = len(grid), len(grid[0])
    # The lower triangle gives the repeating row pattern; cells on and
    # above the main diagonal use the preceding color in that pattern.
    base = []
    for c in range(w - 1):
        values = [grid[r][c] for r in range(c + 1, h) if grid[r][c] != 0]
        if values:
            base.append(max(set(values), key=values.count))
        else:
            base.append(None)
    known = [i for i, v in enumerate(base) if v is not None]
    for i, v in enumerate(base):
        if v is None:
            # Recover any obscured column from the shortest repeating pattern
            # supported by the observed columns.
            base[i] = next((base[j] for j in range(i - 1, -1, -1) if base[j] is not None), None)
    period = len(base)
    for p in range(1, len(base) + 1):
        if all(base[i] == base[i % p] for i in range(p, len(base))):
            period = p
            break
    out = []
    for r in range(h):
        row = []
        for c in range(w):
            if c < r:
                row.append(base[c])
            else:
                row.append(base[(c - 1) % period])
        out.append(row)
    return out
